INSERT INTO lr_questions (section_id, qid, preptest, section, question_number, question_type, stimulus, prompt, correct_choice, is_explained, source_note) SELECT s.id, $batch08$PT156-S4-Q5$batch08$, 156, 4, 5, $batch08$Most Strongly Supported$batch08$, $batch08$Gahagan’s Greenstore sells a large volume of plants. The vast majority are sold wholesale to commercial buyers, most of them to landscape contractors. Gahagan’s also sells gardening implements, most of which are purchased retail by home gardeners.$batch08$, $batch08$Which one of the following is most strongly supported by the information above?$batch08$, $batch08$E$batch08$, true, $batch08$Batch 08; question text from local bank.$batch08$ FROM lr_sections s WHERE s.preptest=156 AND s.section=4 AND NOT EXISTS (SELECT 1 FROM lr_questions q WHERE q.qid=$batch08$PT156-S4-Q5$batch08$) ON CONFLICT DO NOTHING;
INSERT INTO lr_answer_choices (question_id, letter, choice_text, tag, is_correct) SELECT q.id, $batch08$A$batch08$, $batch08$Gahagan’s makes a larger profit from the sale of plants than from the sale of all other products combined.$batch08$, $batch08$Out of Scope$batch08$, false FROM lr_questions q WHERE q.qid=$batch08$PT156-S4-Q5$batch08$ AND NOT EXISTS (SELECT 1 FROM lr_answer_choices c WHERE c.question_id=q.id AND c.letter=$batch08$A$batch08$) ON CONFLICT DO NOTHING;
INSERT INTO lr_answer_choices (question_id, letter, choice_text, tag, is_correct) SELECT q.id, $batch08$B$batch08$, $batch08$Most of those who make regular wholesale purchases from Gahagan’s have never purchased gardening implements from Gahagan’s.$batch08$, $batch08$Unsupported$batch08$, false FROM lr_questions q WHERE q.qid=$batch08$PT156-S4-Q5$batch08$ AND NOT EXISTS (SELECT 1 FROM lr_answer_choices c WHERE c.question_id=q.id AND c.letter=$batch08$B$batch08$) ON CONFLICT DO NOTHING;
INSERT INTO lr_answer_choices (question_id, letter, choice_text, tag, is_correct) SELECT q.id, $batch08$C$batch08$, $batch08$There are more commercial buyers than home gardeners among Gahagan’s regular customers.$batch08$, $batch08$Unsupported$batch08$, false FROM lr_questions q WHERE q.qid=$batch08$PT156-S4-Q5$batch08$ AND NOT EXISTS (SELECT 1 FROM lr_answer_choices c WHERE c.question_id=q.id AND c.letter=$batch08$C$batch08$) ON CONFLICT DO NOTHING;
INSERT INTO lr_answer_choices (question_id, letter, choice_text, tag, is_correct) SELECT q.id, $batch08$D$batch08$, $batch08$Gahagan’s sells a few gardening implements wholesale to landscape contractors.$batch08$, $batch08$Unsupported$batch08$, false FROM lr_questions q WHERE q.qid=$batch08$PT156-S4-Q5$batch08$ AND NOT EXISTS (SELECT 1 FROM lr_answer_choices c WHERE c.question_id=q.id AND c.letter=$batch08$D$batch08$) ON CONFLICT DO NOTHING;
INSERT INTO lr_answer_choices (question_id, letter, choice_text, tag, is_correct) SELECT q.id, $batch08$E$batch08$, $batch08$A plant purchased from Gahagan’s is more likely to have been purchased by a landscape contractor than by a home gardener.$batch08$, $batch08$Correct$batch08$, true FROM lr_questions q WHERE q.qid=$batch08$PT156-S4-Q5$batch08$ AND NOT EXISTS (SELECT 1 FROM lr_answer_choices c WHERE c.question_id=q.id AND c.letter=$batch08$E$batch08$) ON CONFLICT DO NOTHING;
INSERT INTO lr_explanations (question_id, style) SELECT q.id, 'single' FROM lr_questions q WHERE q.qid=$batch08$PT156-S4-Q5$batch08$ AND NOT EXISTS (SELECT 1 FROM lr_explanations e WHERE e.question_id=q.id AND e.style IN ('single','standard')) ON CONFLICT DO NOTHING;
INSERT INTO lr_explanation_steps (explanation_id, position, label, body) SELECT e.id, v.position, v.label, v.body FROM lr_explanations e JOIN lr_questions q ON q.id=e.question_id CROSS JOIN (VALUES (0, $batch08$Statements$batch08$, $batch08$Gahagan's sells many plants. The vast majority go wholesale to commercial buyers, most of them landscape contractors. Gahagan's also sells gardening tools, most of them bought retail by home gardeners.$batch08$), (1, $batch08$Evaluate$batch08$, $batch08$Pause and infer with numbers. Say 90% of plants go wholesale. "Most of them" go to landscape contractors, so more than 45% of all plants. Home gardeners buy retail, and retail is at most the remaining 10%. So a given plant is far more likely to have gone to a contractor.$batch08$), (2, $batch08$Goal$batch08$, $batch08$A plant from Gahagan's was more likely bought by a landscape contractor than a home gardener.$batch08$)) v(position,label,body) WHERE q.qid=$batch08$PT156-S4-Q5$batch08$ AND e.style='single' AND NOT EXISTS (SELECT 1 FROM lr_explanation_steps s WHERE s.explanation_id=e.id) ON CONFLICT DO NOTHING;
INSERT INTO lr_explanation_choice_notes (explanation_id, letter, body) SELECT e.id, v.letter, v.body FROM lr_explanations e JOIN lr_questions q ON q.id=e.question_id CROSS JOIN (VALUES ($batch08$A$batch08$, $batch08$Nothing is said about profit.$batch08$), ($batch08$B$batch08$, $batch08$Most *tools* are bought by home gardeners, but that doesn't tell us whether wholesale buyers have ever bought one.$batch08$), ($batch08$C$batch08$, $batch08$The passage gives sales volume, not head counts. A few contractors could buy huge volumes.$batch08$), ($batch08$D$batch08$, $batch08$"Most" tools sell retail leaves some sold otherwise, but we don't know to whom.$batch08$), ($batch08$E$batch08$, $batch08$Contractors take a large share of the vast majority; home gardeners can only account for part of the small remainder.$batch08$)) v(letter,body) WHERE q.qid=$batch08$PT156-S4-Q5$batch08$ AND e.style='single' AND NOT EXISTS (SELECT 1 FROM lr_explanation_choice_notes n WHERE n.explanation_id=e.id AND n.letter=v.letter) ON CONFLICT DO NOTHING;
